 m(CR, 2, [('Al principio', 'no entendía nada.'), ('De repente', 'se apagó la luz.'), ('Entonces', 'decidimos irnos.'), ('Al final', 'todo salió bien.')], 'Story connectors: start, sudden event, sequence, end.'),
 o(CR, 2, ['De repente se apagaron todas las luces'], 'de repente + sudden event.'),
