 t(CC, 2, 'Une las frases con «como».', 'Llovía. Cogimos un taxi.', ['Como llovía, cogimos un taxi', 'Como llovía cogimos un taxi'], 'como + cause, result.', 'Cogimos un taxi porque llovía.'),
 m(CC, 2, [('Como era tarde,', 'cogimos un taxi.'), ('Cogimos un taxi', 'porque era tarde.'), ('Era tarde.', 'Sin embargo, fuimos andando.'), ('Aunque era tarde,', 'fuimos andando.')], 'como / porque = cause; sin embargo / aunque = contrast.'),
