 e(PO, 2, '—¿Le diste el regalo a Ana? —Sí, *le* lo di ayer.', ['se'], 'le + lo → se lo.', 'Se lo di ayer.'),
 e(PO, 2, '—¿Has leído la novela? —No, todavía no *lo* he leído.', ['la'], 'la novela → la.', 'El libro no lo he leído.'),
 o(PO, 2, ['Te lo cuento mañana'], 'IO before DO, both before the conjugated verb.'),
