 g(RP, 1, 'La novela ___ (contar) la historia de dos hermanas que viven en Cádiz.', 'cuenta', 'Plot summary → present: cuenta (o→ue).', 'La novela contaba…'),
 g(RP, 2, 'En la película, un niño ___ (encontrar) un perro abandonado y decide cuidarlo.', 'encuentra', 'Summaries in the present (o→ue).', 'El niño encontró un perro.'),
 c(RP, 1, 'La serie ___ de un grupo de amigos que abren un restaurante.', ['va', 'es', 'hace'], 'va', 'ir de = to be about.', 'Trata de un grupo de amigos.'),
 c(RP, 2, 'La historia ___ en Barcelona durante los años veinte.', ['ocurre', 'trata', 'va'], 'ocurre', 'ocurrir / pasar / estar ambientada en = set in.', 'Está ambientada en Barcelona.'),
 c(RP, 2, 'Va un hombre a una tienda y le ___ al dependiente: «Quiero un regalo para mi suegra».', ['dice', 'dijo', 'decía'], 'dice', 'Jokes are told in the present.', 'Fue un hombre y le dijo…'),
 e(RP, 2, 'La película *trató* de una familia que gana la lotería.', ['trata'], 'Plot summaries use the present.', 'La película que vi trataba de…'),
 t(RP, 2, 'Resume en presente.', 'El protagonista perdió su trabajo y se fue a vivir al campo.', ['El protagonista pierde su trabajo y se va a vivir al campo'], 'Summary → present.', 'Perdió su trabajo (anecdote in past).'),
 c(RP, 2, '¿Sabes qué me pasó ayer? Pues nada, que ___ en el ascensor y me encuentro a mi exnovio.', ['entro', 'entré', 'entraba'], 'entro', 'Anecdote opened in the past, continued in the present (me encuentro).', 'Entré y me encontré…'),
 g(RP, 3, 'Al final de la película, los dos protagonistas se ___ (dar) cuenta de que están enamorados.', 'dan', 'Present for plot: se dan cuenta.', 'Se dieron cuenta.'),
 m(RP, 2, [('La novela trata de', 'una mujer que busca a su hijo.'), ('Está basada en', 'hechos reales.'), ('La historia ocurre', 'en México en los años cincuenta.'), ('La protagonista es', 'una periodista valiente.')], 'Resources for talking about a book or film.'),
 g(CR, 3, 'Entramos en la casa y, ___ pronto, oímos un ruido arriba.', 'de', 'de pronto = de repente.', 'De repente oímos un ruido.'),
 c(CC, 3, 'Me gusta mucho el cine. ___, este año casi no he ido.', ['Sin embargo', 'Como', 'Porque'], 'Sin embargo', 'sin embargo introduces a contrast in a new sentence.', 'Aunque me gusta el cine…'),
 c(PO, 3, '—¿Quién te ha regalado esa bufanda? —___ ha regalado mi abuela.', ['Me la', 'Me lo', 'La me'], 'Me la', 'IO (me) before DO (la, la bufanda).', 'Te la ha regalado.'),
 g(PO, 3, '—¿Habéis enviado las invitaciones a los invitados? —Sí, ya ___ hemos enviado.', 'se las', 'les + las → se las.', 'Se las enviamos ayer.'),
 c(RP, 3, 'No sé qué ha pasado, pero creo que ___ de un error del banco.', ['se trata', 'trata', 'va'], 'se trata', 'se trata de = it is (a matter of).', 'La película trata de un banco.'),
 o(CC, 2, ['Como no había entradas nos fuimos a cenar'], 'como + cause at the start.'),
